"""Soạn split cố định cho NASA; dữ liệu gold chỉ dùng để đánh giá."""
import hashlib
import json
from collections import Counter
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/"benchmark/advanced"
SOURCE="nasa-se-2016-rev2"


def main():
    cases=[]
    def add(identifier,split,group,question,answer,evidence,calculation=None):
        gold=[{"source_id":SOURCE,"page":page,"reference":ref,"bbox":[0,0,612,792],
               "evidence":description,"evidence_type":group} for page,ref,description in evidence]
        row={"id":identifier,"split":split,"group":group,"question":question,"filter":{},
             "answerable":True,"expected_answer":answer,"gold":gold,"source_review_status":"source_check_proposed"}
        if calculation:row["calculation"]=calculation
        cases.append(row)
    def absent(identifier,split,question,reason,terms):
        cases.append({"id":identifier,"split":split,"group":"unanswerable","question":question,"filter":{},
                      "answerable":False,"expected_behavior":"search_and_abstain","absence_reason":reason,
                      "corpus_check_terms":terms,"source_review_status":"source_check_proposed"})
