    add("ad_t3","dev","table","Theo Table 4.1-1, những bên liên quan ở Phase F là ai?","Customer, NASA Headquarters, operators, safety, planetary protection và public.",[(68,"Table 4.1-1","Phase F row: Customer, NASA Headquarters, operators, safety, planetary protection, public.")])
