    add("ad_c1","dev","chart","Trục đứng của Figure 2.5-1 dùng đại lượng và đơn vị gì?","Cumulative Percentage Life Cycle Cost against Time, tính theo phần trăm, thang từ 0% tới 100%.",[(27,"Figure 2.5-1","Left axis reads Cumulative Percentage Life Cycle Cost against Time and shows 0% through 100%.")])
    add("ad_c2","dev","chart","Trong Figure 4.4-3, di chuyển về hướng nào cho cost-effectiveness cao hơn?","Về góc trên bên trái (upper left).",[(96,"Figure 4.4-3","Source note: Higher values of cost-effectiveness are achieved by moving toward upper left.")])
