    add("at_t3","test","table","Table 4.2-2 liệt kê bốn phương pháp trong trường Verification method là gì?","Test, inspection, analysis, demonstration.",[(83,"Table 4.2-2","Verification method: test, inspection, analysis, demonstration; determined as requirements are developed.")])
    add("at_t4","test","table","Trong hàng Phase D của Table 4.1-1, hai nhóm có tên liên quan trực tiếp đến verification và flight readiness là ai?","Verification team và Flight Readiness Board members.",[(68,"Table 4.1-1","Phase D row includes verification team and Flight Readiness Board members.")])
    add("at_t5","test","table","Table 6.1-2 liệt kê ba loại cơ sở liên quan tới thermal, vibration và radiation với tên gì?","Thermal Chambers, Vibration Labs, Radiation Labs.",[(151,"Table 6.1-2","Facility entries: Thermal Chambers; Vibration Labs; Radiation Labs.")])
