    add("at_c3","test","chart","Figure 2.5-1 ghi Costs Expended ở Concept và Prod/Test bao nhiêu; giá trị Prod/Test gấp mấy lần Concept?","Concept 8%, Prod/Test 50%; 50/8 = 6,25 lần. Đây là các nhãn minh họa trên biểu đồ.",[(27,"Figure 2.5-1","Costs Expended grey bars are Concept 8% and Prod/Test 50%.")],"50 / 8 = 6.25")
    add("at_c4","test","chart","Hai trục của Figure 4.4-3 mang đại lượng và đơn vị mô tả nào?","X: Life-Cycle Cost, expressed in constant dollars; Y: All Aspects of Effectiveness, expressed in quantitative units. Hình không có giá trị tick số cụ thể.",[(96,"Figure 4.4-3","X axis: Life-Cycle Cost, Expressed in Constant Dollars; Y axis: All Aspects of Effectiveness, Expressed in Quantitative Units.")])
    add("at_c5","test","chart","Trong Figure 4.4-3, design concept nào có nguy cơ thất bại đắt đỏ và đám mây bất định nằm ở vị trí nào?","Concept C; gần trục x, tại chi phí cao và effectiveness gần bằng không.",[(96,"Figure 4.4-3","C points to a probability cloud near the x axis at high cost and essentially no effectiveness; note describes high risk of expensive failure.")])
    add("at_m1","test","multi_hop","Chuẩn bị review thiết kế: dùng Figure 2.5-1 giải nghĩa PDR và Table 4.2-2 giải thích trường Verification level.","PDR là Preliminary Design Review; Verification level chỉ cấp trong hệ thống phân cấp mà yêu cầu sẽ được xác minh, ví dụ system/subsystem/element.",[(27,"Figure 2.5-1","PDR = Preliminary Design Review in the legend."),(83,"Table 4.2-2","Verification level specifies the hierarchy level at which requirements will be verified, e.g. system, subsystem, element.")])
