    add("at_x1","test","text","Theo mục 2.6, SE phải tích hợp ngang nhau ba thành phần chính nào?","Hardware, software và human systems integration.",[(28,"","Systems engineering approach must equally address and integrate hardware, software, and human systems integration.")])
